                ["BitTorrent metadata"] = "BitTorrent-Metadaten",
                ["Simulation guide"] = "Simulationsleitfaden",
                ["Build a session in a few steps, then control it from the session list."] = "Erstellen Sie eine Sitzung in wenigen Schritten und steuern Sie sie dann über die Sitzungsliste.",
                ["Interception guide"] = "Abfanganleitung",
                ["Follow tracker activity observed through the local proxy."] = "Verfolgen Sie die Tracker-Aktivität, die über den lokalen Proxy beobachtet wird.",
                ["Activity guide"] = "Aktivitätsleitfaden",
                ["Use the event stream to understand what the proxy and simulations are doing."] = "Verwenden Sie den Ereignisstrom, um zu verstehen, was der Proxy und die Simulationen tun.",
                ["Settings guide"] = "Einstellungshandbuch",
                ["Adjust the local proxy behavior and save the changes from this tab."] = "Passen Sie das lokale Proxy-Verhalten an und speichern Sie die Änderungen auf dieser Registerkarte.",
                ["Platform guide"] = "Plattform-Leitfaden",
                ["Manage system integration and HTTPS trust for the current machine."] = "Verwalten Sie die Systemintegration und HTTPS-Vertrauen für die aktuelle Maschine.",
                ["Overview guide"] = "Überblicksleitfaden",
                ["Use this tab to check the current runtime at a glance."] = "Verwenden Sie diese Registerkarte, um die aktuelle Laufzeit auf einen Blick zu überprüfen.",
                ["1. Import a torrent"] = "1. Importieren Sie einen Torrent",
                ["The torrent file provides the metadata and the tracker list used by the session."] = "Die Torrent-Datei liefert die Metadaten und die von der Sitzung verwendete Tracker-Liste.",
                ["In Torrent file, click Browse… and select one .torrent file."] = "Klicken Sie in der Torrent-Datei auf Durchsuchen... und wählen Sie eine .torrent-Datei aus.",
                ["Check the selected tracker, info hash and size in Torrent info."] = "Überprüfen Sie den ausgewählten Tracker, den Info-Hash und die Größe in den Torrent-Informationen.",
                ["2. Set the announce profile"] = "2. Legen Sie das Ankündigungsprofil fest",
                ["The main form contains the values that will be announced to the selected tracker."] = "Das Hauptformular enthält die Werte, die dem ausgewählten Tracker mitgeteilt werden.",
                ["Set upload and download speeds, or keep + Random values enabled to vary them between the configured limits."] = "Legen Sie Upload- und Download-Geschwindigkeiten fest oder lassen Sie + Zufallswerte aktiviert, um sie zwischen den konfigurierten Limits zu variieren.",
                ["Choose the client profile and the finished percentage in Options."] = "Wählen Sie unter Optionen das Kundenprofil und den fertigen Prozentsatz aus.",
                ["Use the Stop controls only when the session should end automatically."] = "Verwenden Sie die Stopp-Steuerelemente nur, wenn die Sitzung automatisch beendet werden soll.",
                ["3. Review Advanced"] = "3. Erweitertes Review",
                ["Advanced contains the tracker identity and optional outbound proxy settings."] = "Advanced enthält die Tracker-Identität und optionale ausgehende Proxy-Einstellungen.",
                ["Listening port and Peers requested control the identity sent by the session."] = "Der angeforderte Listening-Port und Peers steuern die von der Sitzung gesendete Identität.",
                ["Proxy address is optional; enter an absolute address when the tracker connection must go through a proxy."] = "Die Proxy-Adresse ist optional; geben Sie eine absolute Adresse ein, wenn die Tracker-Verbindung einen Proxy durchlaufen muss.",
                ["4. Add, then start"] = "4. Hinzufügen, dann starten",
                ["Adding saves the configuration. Starting is the explicit action that begins tracker communication."] = "Hinzufügen speichert die Konfiguration. Start ist die explizite Aktion, mit der die Tracker-Kommunikation beginnt.",
                ["Click Add session to create the session in the list."] = "Klicken Sie auf Sitzung hinzufügen, um die Sitzung in der Liste zu erstellen.",
                ["Select the new session, then click ▶  Start. The action changes to ■  Stop while it is running."] = "Wählen Sie die neue Sitzung aus und klicken Sie dann auf ▶  Start. Die Aktion wechselt zu ■  Anhalten, während sie ausgeführt wird.",
                ["5. Monitor the session"] = "5. Überwachen Sie die Sitzung",
                ["The session row shows state, ratio, transfer counters, peers and the next announce time."] = "Die Sitzungszeile zeigt Status, Verhältnis, Übertragungszähler, Peers und die nächste Ankündigungszeit an.",
                ["Use Manual update for an immediate update while the session is running."] = "Verwenden Sie die manuelle Aktualisierung für eine sofortige Aktualisierung, während die Sitzung ausgeführt wird.",
                ["Select a stopped session and click Remove when it is no longer needed."] = "Wählen Sie eine gestoppte Sitzung aus und klicken Sie auf Entfernen, wenn sie nicht mehr benötigt wird.",
                ["Start the proxy"] = "Starten Sie den Proxy",
                ["Use Start in the top bar after checking the proxy settings."] = "Verwenden Sie Start in der oberen Leiste, nachdem Sie die Proxy-Einstellungen überprüft haben.",
                ["The status indicator in the header shows whether the proxy is active or paused."] = "Die Statusanzeige im Header zeigt an, ob der Proxy aktiv oder pausiert ist.",
                ["Read tracked sessions"] = "Verfolgte Sitzungen lesen",
                ["Each row contains the torrent hash, tracker, peers, status, counters and the last announce time."] = "Jede Zeile enthält den Torrent-Hash, Tracker, Peers, Status, Zähler und den letzten Ankündigungszeitpunkt.",
                ["Read the latest events"] = "Lesen Sie die neuesten Ereignisse",
                ["Change a value"] = "Einen Wert ändern",
                ["Edit the fields, review the toggles, then click Save changes in the Settings tab."] = "Bearbeiten Sie die Felder, überprüfen Sie die Umschalter und klicken Sie dann auf der Registerkarte Einstellungen auf Änderungen speichern.",
                ["Configure the qBittorrent client"] = "Konfigurieren des qBittorrent-Clients",
                ["Route qBittorrent tracker announces through the local XRatio proxy before checking the ratio."] = "Route qBittorrent-Tracker meldet sich über den lokalen XRatio-Proxy, bevor das Verhältnis überprüft wird.",
                ["Route tracker announces through the local XRatio HTTP proxy before checking the ratio."] = "Der Routen-Tracker meldet sich über den lokalen XRatio-HTTP-Proxy, bevor er das Verhältnis überprüft.",
                ["Start XRatio and verify that the header shows HTTP/HTTPS active on 127.0.0.1:3773."] = "Starten Sie XRatio und vergewissern Sie sich, dass der Header HTTP/https aktiv auf 127.0.0.1:3773 anzeigt.",
                ["In qBittorrent, open Tools > Options > Connection."] = "Öffnen Sie in qBittorrent Extras > Optionen > Verbindung.",
                ["Under Proxy Server, choose HTTP, set Host to 127.0.0.1 and Port to 3773."] = "Wählen Sie unter Proxy Server die Option http, setzen Sie Host auf 127.0.0.1 und Port auf 3773.",
                ["Enable Perform hostname lookup via proxy and Use proxy for BitTorrent purposes. Leave Use proxy for peer connections disabled because XRatio handles tracker announces only."] = "Aktivieren Sie Perform hostname lookup via proxy und Use proxy for BitTorrent purposes. Lassen Sie den Proxy für Peer-Verbindungen deaktiviert, da XRatio Tracker nur ankündigt.",
                ["For Deluge, Transmission, Tixati, BiglyBT, Vuze or another client, open Settings/Preferences and find Connection, Network or Proxy. Use HTTP, server 127.0.0.1 and port 3773. Enable tracker/BitTorrent proxying and leave peer connections disabled when that option is separate."] = "Für Deluge, Transmission, Tixati, BiglyBT, Vuze oder einen anderen Client öffnen Sie Einstellungen/Präferenzen und suchen Sie Verbindung, Netzwerk oder Proxy. Verwenden Sie HTTP, Server 127.0.0.1 und Port 3773. Aktivieren Sie Tracker/BitTorrent-Proxying und lassen Sie Peer-Verbindungen deaktiviert, wenn diese Option separat ist.",
                ["In XRatio Settings > Announce behavior, download reporting is kept at zero. Use Pause or Stop when you need to suspend announce rewriting; Pretend to seed remains optional."] = "Unter XRatio-Einstellungen > Verhalten ankündigen wird das Download-Reporting auf Null gehalten. Verwenden Sie Pause oder Stopp, wenn Sie das Neuschreiben von Ankündigungen unterbrechen müssen. Geben Sie vor, dass der Seed optional bleibt.",
                ["Click Apply, then OK. Check the Interception tab in XRatio for the next tracker announce."] = "Klicken Sie auf Übernehmen und dann auf OK. Überprüfen Sie die Registerkarte Abfangen in XRatio für die nächste Tracker-Ankündigung.",
                ["If the ratio still changes, check the port, proxy type and tracker policy. A proxy cannot force a tracker to accept or freeze a ratio."] = "Wenn sich das Verhältnis immer noch ändert, überprüfen Sie den Port, den Proxy-Typ und die Tracker-Richtlinie. Ein Proxy kann einen Tracker nicht zwingen, ein Verhältnis zu akzeptieren oder einzufrieren.",
                ["Keep the scope clear"] = "Halten Sie den Geltungsbereich frei",
                ["Keep Listen on localhost only enabled unless you have a specific, authorized reason to change the deployment boundary."] = "Nur auf localhost hören aktivieren, es sei denn, Sie haben einen bestimmten, autorisierten Grund, die Bereitstellungsgrenze zu ändern.",
                ["Use only torrents and trackers for which you are authorized, and follow the tracker rules."] = "Verwenden Sie nur Torrents und Tracker, für die Sie autorisiert sind, und befolgen Sie die Tracker-Regeln.",
                ["Startup behavior"] = "Startverhalten",
                ["Safety note"] = "Sicherheitshinweis",
                ["Use simulation only with torrents and trackers for which you are authorized."] = "Verwenden Sie die Simulation nur mit Torrents und Trackern, für die Sie autorisiert sind.",
                ["This guide follows the active XRatio tab."] = "Diese Anleitung folgt der aktiven Registerkarte XRatio.",
                ["If an action is unavailable, select the relevant row or complete the required fields first."] = "Wenn eine Aktion nicht verfügbar ist, wählen Sie die entsprechende Zeile aus oder füllen Sie zuerst die erforderlichen Felder aus.",
