                ["Use the Stop controls only when the session should end automatically."] = "Usa i controlli di Stop solo quando la sessione deve terminare automaticamente.",
                ["3. Review Advanced"] = "3. Rivedi Avanzate",
                ["Advanced contains the tracker identity and optional outbound proxy settings."] = "Avanzate contiene l'identità del tracker e le impostazioni opzionali del proxy in uscita.",
                ["Listening port and Peers requested control the identity sent by the session."] = "La porta di ascolto e i Peer richiesti controllano l'identità inviata dalla sessione.",
                ["Proxy address is optional; enter an absolute address when the tracker connection must go through a proxy."] = "L'indirizzo del proxy è facoltativo; inserire un indirizzo assoluto quando la connessione al tracker deve passare attraverso un proxy.",
                ["4. Add, then start"] = "4. Aggiungi, quindi avvia",
                ["Adding saves the configuration. Starting is the explicit action that begins tracker communication."] = "L'aggiunta salva la configurazione. L'avvio è l'azione esplicita che inizia la comunicazione con il tracker.",
                ["Click Add session to create the session in the list."] = "Clicca su Aggiungi sessione per creare la sessione nell'elenco.",
                ["Select the new session, then click ▶  Start. The action changes to ■  Stop while it is running."] = "Seleziona la nuova sessione, quindi clicca su ▶  Avvia. L'azione cambia in ■  Ferma mentre è in esecuzione.",
                ["5. Monitor the session"] = "5. Monitora la sessione",
                ["The session row shows state, ratio, transfer counters, peers and the next announce time."] = "La riga della sessione mostra stato, rapporto, contatori di trasferimento, peer e il tempo del prossimo annuncio.",
                ["Use Manual update for an immediate update while the session is running."] = "Usa Aggiornamento manuale per un aggiornamento immediato mentre la sessione è in esecuzione.",
                ["Select a stopped session and click Remove when it is no longer needed."] = "Seleziona una sessione fermata e clicca Rimuovi quando non è più necessaria.",
                ["Start the proxy"] = "Avvia il proxy",
