                ["2. Set the announce profile"] = "2. Defina o perfil de anúncio",
                ["The main form contains the values that will be announced to the selected tracker."] = "O formulário principal contém os valores que serão anunciados ao tracker selecionado.",
                ["Set upload and download speeds, or keep + Random values enabled to vary them between the configured limits."] = "Defina as velocidades de upload e download, ou mantenha os valores + Aleatórios ativados para variá-los entre os limites configurados.",
