                ["Listening port and Peers requested control the identity sent by the session."] = "A porta de escuta e os pares solicitados controlam a identidade enviada pela sessão.",
                ["Proxy address is optional; enter an absolute address when the tracker connection must go through a proxy."] = "O endereço do proxy é opcional; insira um endereço absoluto quando a conexão com o rastreador precisar passar por um proxy.",
                ["4. Add, then start"] = "4. Adicionar, depois iniciar",
                ["Adding saves the configuration. Starting is the explicit action that begins tracker communication."] = "Adicionar salva a configuração. Iniciar é a ação explícita que inicia a comunicação com o rastreador.",
                ["Click Add session to create the session in the list."] = "Clique em Adicionar sessão para criar a sessão na lista.",
                ["Select the new session, then click ▶  Start. The action changes to ■  Stop while it is running."] = "Selecione a nova sessão e, em seguida, clique em ▶ Iniciar. A ação muda para ■ Parar enquanto estiver em execução.",
                ["5. Monitor the session"] = "5. Monitorar a sessão",
                ["The session row shows state, ratio, transfer counters, peers and the next announce time."] = "A linha da sessão mostra estado, razão, contadores de transferência, pares e o próximo horário de anúncio.",
                ["Use Manual update for an immediate update while the session is running."] = "Use Atualização Manual para uma atualização imediata enquanto a sessão estiver em execução.",
                ["Select a stopped session and click Remove when it is no longer needed."] = "Selecione uma sessão parada e clique em Remover quando ela não for mais necessária.",
                ["Start the proxy"] = "Inicie o proxy",
