                ["Start XRatio and verify that the header shows HTTP/HTTPS active on 127.0.0.1:3773."] = "قم بتشغيل XRatio وتأكد من أن الرأس يظهر HTTP/HTTPS نشط على 127.0.0.1:3773.",
                ["In qBittorrent, open Tools > Options > Connection."] = "في qBittorrent، افتح أدوات > خيارات > الاتصال.",
                ["Under Proxy Server, choose HTTP, set Host to 127.0.0.1 and Port to 3773."] = "تحت خادم الوكيل، اختر HTTP، واضبط المضيف على 127.0.0.1 والمنفذ على 3773.",
                ["Enable Perform hostname lookup via proxy and Use proxy for BitTorrent purposes. Leave Use proxy for peer connections disabled because XRatio handles tracker announces only."] = "تمكين إجراء بحث عن اسم المضيف عبر الوكيل واستخدام الوكيل لأغراض BitTorrent. اترك استخدام الوكيل للاتصالات بين الأقران معطلاً لأن XRatio يتعامل فقط مع إعلانات المتعقب.",
                ["For Deluge, Transmission, Tixati, BiglyBT, Vuze or another client, open Settings/Preferences and find Connection, Network or Proxy. Use HTTP, server 127.0.0.1 and port 3773. Enable tracker/BitTorrent proxying and leave peer connections disabled when that option is separate."] = "بالنسبة لـ Deluge أو Transmission أو Tixati أو BiglyBT أو Vuze أو أي عميل آخر، افتح الإعدادات/التفضيلات وابحث عن الاتصال أو الشبكة أو الوكيل. استخدم HTTP، الخادم 127.0.0.1 والمنفذ 3773. فعّل وكيل المتعقب/BitTorrent واترك اتصالات النظراء معطلة عندما يكون هذا الخيار منفصلاً.",
                ["In XRatio Settings > Announce behavior, download reporting is kept at zero. Use Pause or Stop when you need to suspend announce rewriting; Pretend to seed remains optional."] = "في إعدادات XRatio > سلوك الإعلانات، يتم الحفاظ على تقارير التنزيل عند الصفر. استخدم الإيقاف المؤقت أو الإيقاف عندما تحتاج إلى تعليق إعادة كتابة الإعلان؛ يبقى خيار التظاهر بالتوزيع اختياريًا.",
                ["Click Apply, then OK. Check the Interception tab in XRatio for the next tracker announce."] = "انقر على تطبيق، ثم موافق. تحقق من علامة تبويب الاعتراض في XRatio للإعلان عن المتعقب التالي.",
                ["If the ratio still changes, check the port, proxy type and tracker policy. A proxy cannot force a tracker to accept or freeze a ratio."] = "إذا استمر تغير النسبة، تحقق من المنفذ ونوع البروكسي وسياسة المتتبع. لا يمكن للبروكسي إجبار المتتبع على قبول أو تجميد النسبة.",
                ["Keep the scope clear"] = "حافظ على وضوح النطاق",
                ["Keep Listen on localhost only enabled unless you have a specific, authorized reason to change the deployment boundary."] = "ابق خيار الاستماع على localhost مفعلًا إلا إذا كان لديك سبب محدد ومصرح به لتغيير حدود النشر.",
                ["Use only torrents and trackers for which you are authorized, and follow the tracker rules."] = "استخدم فقط التورنت والمتتبعات التي لك الحق باستخدامها، واتبع قواعد المتعقب.",
                ["Startup behavior"] = "سلوك بدء التشغيل",
                ["Safety note"] = "ملاحظة السلامة",
                ["Use simulation only with torrents and trackers for which you are authorized."] = "استخدم المحاكاة فقط مع التورنتات والمتعقبات التي لديك صلاحية لاستخدامها.",
                ["This guide follows the active XRatio tab."] = "يتبع هذا الدليل علامة تبويب XRatio النشطة.",
                ["If an action is unavailable, select the relevant row or complete the required fields first."] = "إذا كان الإجراء غير متاح، فاختر الصف المعني أو أكمل الحقول المطلوبة أولاً.",
